def a(s):return '\n'.join(['4 minuto: Tiyakin ang mga termino at layunin ng pag-aaral.','10 minuto: Basahin ang teksto at ayusin ang relasyon ng tagubilin sa drawing at trabaho.','7 minuto: Isulat ang pasya sa tiyak na sitwasyon at hindi pa natiyak na bagay.','7 minuto: '+s,'2 minuto: Ibuod ang mahahalagang punto at gustong tiyakin sa lugar ng trabaho.'])
m.AUTHORED.update({
43:dict(title='Pagtitiyak sa drawing paper at lettering at pagpili ng drawing ayon sa gamit',objective='Ipaliwanag ang pagiging nababasa ng papel at lettering at papel ng part, assembly, at layout drawings.',paragraphs=[
('Laki at direksiyon ng papel','Sa mechanical drawing sa materyal na ito, inuuna ang A-series paper at pinipili ang laking malinaw na nagpapakita ng bagay. Karaniwang pahalang ang mahabang gilid; maaari ring portrait ang A4. Hindi nagiging tama ang nilalaman dahil malaki ang papel. Sa kinopya o pinaliit na print, tiyaking sapat na nababasa ang mga linya at letra.'),
('Pagbasa ng character height','Ipinapakita ang laki ng drawing letters sa character height. Inililista sa materyal ang 3.5, 5, 7, 10mm para sa kanji at 2.5, 3.5, 5, 7, 10mm para sa kana at alphanumeric characters. Kung malabo ang decimal point o bahagi ng digit, huwag magtrabaho batay sa hula; humiling ng nababasang aprubadong drawing. Huwag ipagkamali ang print scaling bilang pagbabago ng nakasulat na dimension value.'),
('Layunin ng trabaho at papel ng drawing','Para sa paggawa ng indibidwal na piyesa ang part drawing, para sa pagsasama ng piyesa ang assembly drawing, at para sa installation location ng makina ang layout drawing. Kung kailangang tiyakin ang lokasyon ng kagamitan, hindi sapat na tingnan lamang ang hole dimensions ng piyesa. Tiyakin ang uri at saklaw ng drawing na kailangan sa trabaho at itanong sa nakatalaga ang kulang na impormasyon.')],terms=['Papel na may takdang sukat para sa pagguhit ng drawing.','Taas na nagpapahayag ng laki ng drawing lettering.','Drawing na nagpapakita ng impormasyong kailangan sa paggawa ng piyesa.','Drawing na nagpapakita ng installation location ng makina at katulad nito.'],fullActivity=a('Gumawa ng talaan ng uri ng drawing na ibibigay sa machining, assembly, at installation personnel. Iguhit sa papel ang A3 landscape at A4 portrait layouts at sumulat ng tanong kapag hindi mabasa ang decimal point.'),safety=['Huwag mag-machine batay sa hula sa malabong printed dimension. Ipagpaliban ang kaukulang trabaho hanggang matiyak ang nababasang drawing.'],summary='Mahalagang nababasa ang papel at lettering. Gamitin ang drawing na angkop sa machining, assembly, o installation.'),
44:dict(title='Pag-uugnay ng viewing direction at view position sa third-angle projection',objective='Ipaliwanag ang ayos ng top at side views sa third-angle projection at itugma ang front view sa ibang views.',paragraphs=[
('Pagtingin sa solid mula sa maraming direksiyon','Ipinapakita ng projection drawing ang hugis ng solid sa patag na plane. Sa third-angle projection, ang top view mula sa itaas ay nasa itaas ng front view, at ang right-side view mula sa kanan ay nasa kanan nito. Tiyakin muna ang front view at projection-method instruction upang hindi ipaghalo ang kaliwa o kanan ng papel at ang direksiyon ng pagtingin sa aktuwal na bagay.'),
('Pagpili ng front view ayon sa hugis at layunin','Tinatawag ding principal view ang front view at nililinaw nito ang hugis at function. Pinipili ito ayon sa direksiyon ng paggamit sa assembly drawing at posisyon sa pangunahing machining process sa part drawing. Mahalaga ring hindi labis ang hidden lines. Huwag ituring na front view ang pinakamalaking drawing nang hindi tinitiyak.'),
('Pagtutugma ng parehong bahagi sa tatlong views','Isaalang-alang sa papel ang piyesang may butas sa itaas at step sa gilid. Hindi matitiyak ang hole depth mula sa top view lamang, kaya itugma sa front o section-view instructions. Gabay din ang projection symbol malapit sa title block. Kung hindi tugma ang ayos, huwag basta baligtarin ang drawing; itanong ang projection method at viewing direction.')],terms=['Drawing na nagpapakita sa plane ng hugis ng solid mula sa isang direksiyon.','Paraan ng pagguhit na inilalagay ang projection views sa posisyong ayon sa viewing direction.','Front view na pangunahing nagpapakita ng hugis at function.','Projection view ng bagay mula sa itaas.'],fullActivity=a('Sa paligid ng front view, ipakita sa mga arrow ang pagtingin mula sa itaas, kanan, at kaliwa. Markahan ang posisyon ng top at right-side views sa third-angle projection at isulat ang karagdagang view o tagubiling kailangan upang hatulan ang hole depth.'),safety=['Huwag baligtarin sa sariling paraan at i-machine ang drawing na hindi malinaw ang projection o viewing direction. Tiyakin ang tamang orientation kasama ng nakatalaga.'],summary='Sa third-angle projection, nasa itaas ang view mula sa itaas at nasa kanan ang view mula sa kanan. Tiyakin ang projection at front view bago pagtugmain ang views.'),
45:dict(title='Paghiwalay sa cut material at internal space sa section view',objective='Ipaliwanag ang virtual cutting at hatching at itugma ang nakatagong hugis sa ibang views.',paragraphs=[
('Hindi nangangahulugang aktuwal na pinutol','Sa section view, ipinapalagay na pinutol ang bagay at inalis ang harap upang ipakita ang loob. Mas madaling maunawaan ang internal holes at steps kaysa sa maraming hidden lines. Pagpapahayag ito ng hugis, hindi machining command upang aktuwal na putulin ang produkto.'),
('Paghiwalay ng hatching at hole','Karaniwang may hatching ang material surface sa virtual cut. Sa cylindrical part, ihiwalay ang materyal sa cut section at ang espasyo ng internal diameter. Huwag ituring na hole ang lahat ng hatched areas o groove-machining instruction ang mga pahilis na linya mismo. Tiyakin din ang dimensions at ibang projection views.'),
('Hindi lahat ay ginagawang section sa parehong paraan','May bahaging hindi sine-section kung walang dagdag na paliwanag ang pagputol at makahahadlang pa sa pag-unawa. Kaya hindi masasabing hollow ang lahat ng walang pahilis na linya. Kung hindi malinaw ang cutting position o target part, tiyakin ang assembly drawing, part drawing, at itinakdang section range bago ipaliwanag ang internal shape.')],terms=['Drawing na nagpapakita ng loob sa pamamagitan ng ipinagpalagay na pagputol.','Bahaging lumilitaw ang materyal sa virtual cutting plane.','Pahilis na mga linyang nagpapakita ng cut material at katulad nito.','Bahaging walang materyal at may bakanteng loob.'],fullActivity=a('Iguhit sa papel ang hollow tube at kulayan nang magkaiba ang cut material at internal-diameter space. Ibuod kung bakit hindi laging hole ang walang hatching at magsulat ng tatlong bagay na titiyakin sa ibang views.'),safety=['Huwag magsimula ng cutting dahil lamang sa section representation. Hiwalay na tiyakin ang machining instruction at drawing na nagpapaliwanag ng hugis.'],summary='Virtual representation ang section view upang ipaliwanag ang loob. Itugma sa ibang views ang cut material, space, at bahaging hindi sine-section.'),
46:dict(title='Pagbasa ng kinakailangang haba mula sa dimension lines at numero',objective='Ipaliwanag ang dimension at extension lines at yunit ng haba at anggulo; itanong ang magkakasalungat na duplicate instructions.',paragraphs=[
('Pagbasa ng requirement sa finished state','Mahalaga ang dimensions sa function at paggawa ng piyesa at karaniwang nagpapakita ng finished dimensions. Ang labis na pag-uulit ng parehong dimension ay maaaring magdulot ng magkaibang halaga sa pagbabago. Kahit malaki ang print, basahin ang nakasulat na dimension sa halip na ipalit ang ruler measurement ng linya sa papel.'),
('Papel ng dalawang uri ng linya','Tumutugma ang dimension line sa tinutukoy na haba o anggulo at may arrowheads at katulad nito sa dulo. Nililinaw ng extension lines kung aling dalawang lokasyon ang tinutukoy. Magkaiba ang side length, chord length, arc length, at angle. Huwag kunin ang numero lamang; sundan ang endpoints at extension lines upang tiyakin ang target.'),
('Pagtitiyak sa yunit at duplicates','Karaniwang mm ang haba sa mechanical drawing at maaaring walang mm sa bawat dimension value. Ang anggulo naman ay nasa degrees at katulad na yunit, kaya magbabago ang kahulugan kahit pareho ang numero. Tiyakin muna ang unit instruction. Kung may magkaibang dimensions para sa parehong bagay, huwag piliin ang paborable; ipakita ang lugar at magtanong.')],terms=['Linyang nagpapakita ng dimension at may endpoint symbols.','Pantulong na linyang nagpapakita ng mga lokasyong saklaw ng dimension.','Dimension na kailangan sa kondisyong tapos na ang machining at katulad nito.','Dimension na paulit-ulit na nakasulat para sa parehong bagay.'],fullActivity=a('Iguhit nang magkaiba ang dimension at extension lines sa square plate. Ihiwalay ang haba na 24 at angle na 24° sa talaan at gumawa ng tanong para sa magkaibang value sa parehong lugar.'),safety=['Huwag ayusin ang contradiction ng duplicate dimensions sa sariling pasya sa trabaho. Huwag magpatuloy sa machining bago matiyak ang aprubadong requirement.'],summary='Basahin nang magkakasama ang value, unit, at target location. Tiyakin ang papel ng linya at finished condition at itanong ang contradiction.'),
47:dict(title='Pag-uugnay ng detail at reference dimensions sa machining information',objective='Ihiwalay ang radius, diameter, thickness, at hole-machining instructions sa reference dimensions na may parentheses.',paragraphs=[
('Pagbasa ng simbolo kasama ang target','R ang radius, φ ang diameter, at t ang plate thickness. May halimbawang inaalis ang simbolo kung malinaw ang kahulugan mula sa dimension-line direction at endpoints. Huwag pasyahan ang uri dahil lamang wala ang isang simbolo; tiyakin ang target sa drawing at dalawang dulo ng dimension line. Halimbawa, radius6 ang R6 at diameter6 ang φ6, kaya hindi pareho ang hinihinging hugis.'),
('Pagtiyak sa machining condition bukod sa hole diameter','Kung kailangang ihiwalay ang paraan ng paggawa ng butas, ipinapakita rin ang nominal tool size at machining method. Huwag ituring na iisang proseso ang drilled hole at finish reaming dahil lamang pareho ang nominal diameter. May notation na inaalis ang depth sa through hole, ngunit huwag ipasyang lahat ay through holes dahil lamang walang nakikitang depth; itugma sa ibang views at instructions.'),
('Pagpapanatili ng kahulugan ng parentheses','Reference dimensions ang halagang para sa sanggunian at may parentheses. Maaaring halaga itong nakukuha mula sa ibang dimensions. Kapag nawala ang parentheses sa pagkopya, maaaring mapagkamalan ang papel ng dimension. Huwag ipalit ang parenthesized value lamang bilang batayan ng machining o pass/fail; tiyakin ang pangunahing instruction at inspection plan.')],terms=['Haba mula sa gitna hanggang circumference ng bilog.','Kapal ng plate.','Butas na tumatagos sa buong bahagi.','Dimension na may parentheses at ipinapakita bilang sanggunian.'],fullActivity=a('Kopyahin ang R8, φ8, t2.0, at (18) kasama ang kani-kanilang papel. Ihiwalay ang checks para sa drilled hole at reaming at isulat ang view o tanong kapag hindi malinaw ang hole depth.'),safety=['Huwag gumawa ng butas sa sariling pasya kung hindi malinaw ang depth o machining method. Huwag ipalit ang reference dimension bilang pormal na inspection condition nang walang pahintulot.'],summary='Basahin ang detail symbols at machining method at panatilihin ang parentheses ng reference dimensions. Tiyakin sa buong drawing ang kulang na instructions.'),
48:dict(title='Pagtutugma ng geometric-tolerance target at datum',objective='Ihiwalay ang requirements sa hugis at orientation na hindi sapat ipahayag ng size dimensions at ang reference datum.',paragraphs=[
('Requirements na hindi matitiyak sa size range lamang','Kahit nasa itinakdang range ang diameter o haba, hindi laging natutugunan ang flatness, axis orientation, o position. Itinatakda ng geometric tolerances ang straightness, flatness, roundness, parallelism, perpendicularity, position, at iba pa. Magkaiba ang katangiang sinusuri ayon sa uri, kaya huwag ituring na lahat ay nasuri matapos ang isang size measurement.'),
('Pagbasa sa frame at pagsunod sa target','Ipinapakita sa geometric-tolerance frame ang geometric-characteristic symbol, tolerance value, at datum reference kung kailangan. Sa halimbawang papel na “parallelism, 0.08, B,” basahin hindi lamang ang 0.08 kundi kung ano ang kailangang parallel sa datumB. Tiyakin din mula sa arrow attachment at katulad nito kung surface o axis ang tinutukoy.'),
('Huwag basta palitan ang reference','Datum ang reference sa geometric tolerance. Maaaring magkaiba ang attachment location sa drawing para sa surface at axis. Huwag magdagdag sa sarili ng hindi kailangang reference sa individual-form requirement gaya ng flatness. Kung hindi matukoy ang datum surface o axis, huwag tiyakin ang measuring method; kumpirmahin sa nakatalaga ang target, reference, at applicable standard.')],terms=['Instruction ng pinapayagang variation sa form, orientation, position, at katulad nito.','Geometric characteristic tungkol sa pagiging patag ng surface.','Geometric characteristic tungkol sa pagiging parallel sa reference.','Reference sa pag-unawa sa geometric tolerance.'],fullActivity=a('Ihiwalay ang requirements sa haba, flatness, at parallelism. Sa halimbawang papel na “parallelism0.08, datumB,” ilagay ang target at reference at gumawa ng measurement inquiry kapag hindi malinaw ang target.'),safety=['Huwag ipasa ang hindi pa malinaw na geometric-tolerance reference o target gamit ang pinakamalapit na surface bilang datum. Sundin ang aprubadong measuring method.'],summary='Pagsamahin sa pagbasa ang characteristic, value, target, at kinakailangang reference. Hindi kapalit ang size-measurement result lamang.'),
49:dict(title='Pagsunod sa target location ng surface-texture at welding symbols',objective='Hiwalay na itanong ang surface parameters at welding type, position, at groove preparation.',paragraphs=[
('Huwag kunin ang surface-texture value lamang','Nakaaapekto sa machine performance ang surface condition, kabilang ang waviness at roughness. Sa drawing, isinasama ang parameters gaya ng Ra o Rz at value sa simbolo at itinuturo ang target surface nang direkta o sa leader line. Magkaiba ang kahulugan ng parehong numero kung iba ang parameter. Huwag hiramin ang value ng ibang surface; tiyakin din ang machining-related symbol, target surface, at measuring conditions.'),
('Paghiwalay sa welding type at position','May reference line at basic symbol ang welding notation, kasama ang kinakailangang dimensions at supplemental instructions. Ipinaghihiwalay ng basic symbols ang I-groove, V-groove, single-bevel groove, fillet welds, at iba pa. Sa notation na ipinapakita sa materyal, ang basic symbol sa ibaba ng reference line ay arrow side at sa itaas ay opposite side. Sa aktuwal na drawing, tiyakin din ang applicable standard at notation method; huwag baligtarin ang drawing at magpasya sa sarili ng position.'),
('Pagtitiyak sa bahaging ihahanda at supplemental instructions','Groove preparation ang hugis ng member edge na inihahanda para sa welding. Maaaring gamitin ang bent arrow upang tukuyin ang member na ihahanda, ngunit may hindi bent na halimbawa kapag malinaw ang target at katulad na sitwasyon. Huwag piliin ang gagawing side mula lamang sa pagkabaluktot ng arrow; tiyakin nang magkakasama ang basic symbol, target member, dimensions, at supplemental instructions. Hindi pahintulot ang pagbasa ng symbol upang laktawan ang work qualifications o safety procedures.')],terms=['Kondisyon ng surface kabilang ang roughness at waviness.','Linyang nag-uugnay ng simbolo o paliwanag sa target location.','Reference line kung saan inilalagay ang basic welding symbols at katulad nito.','Hugis ng member edge na inihahanda para sa welding.'],fullActivity=a('Kopyahin nang hiwalay ang Ra at Rz ng dalawang surfaces. Gamit ang notation ng materyal, ihiwalay sa salita ang arrow-side at opposite-side welding. Gumawa ng tanong kapag hindi malinaw kung aling member ang gagawan ng groove preparation.'),safety=['Huwag mag-machine habang malabo ang welding position o groove shape. Sa aktuwal na trabaho, tugunan ang itinakdang qualifications, edukasyon, fire prevention, at protective equipment.'],summary='Tiyakin ang parameter at target surface sa surface texture at ang type at position sa welding. Isama ang applicable standard at supplemental instructions.')
})
